head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[gridView > P > dataDragDropCell]<br/>Drag&Drop 으로 Cell 단위의 데이터 이동을 허용할지 설정합니다.",
    "validation" : [
        "dataDragDropCell=true 이면 dataDragDrop 속성은 무시됩니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target/dataList 있으면 삭제
    if (typeof target1 !== 'undefined') { target1.remove(); }
    if (typeof target2 !== 'undefined') { target2.remove(); }
    if (typeof dlt_src !== 'undefined') { $p.data.remove("dlt_src"); }
    if (typeof dlt_dst !== 'undefined') { $p.data.remove("dlt_dst"); }

    // con : 공통 gdl_boolean 바인딩 (getText() 로 '' 미설정 / 'true' / 'false' 판단)
    //  - dataDragDropCell 만 토글한다. dataDragDrop(Row 이동) 은 소스 그리드(target1)에 true 로 고정.
    let vCell = con_dataDragDropCell.getText();

    // 사용법 안내 라벨 (target 생성 전 가장 먼저 생성)
    //  - target1=Drag 소스(dlt_src, 4행), target2=Drop 대상(dlt_dst, 2행, 서로 다른 DataList).
    //  - dataDragDrop=true 고정. con(dataDragDropCell) 값에 따라: true 면 Cell 단위 이동(dataDragDrop 무시 -> 행 수 불변, 특정 셀만 변경) / false 또는 미설정이면 Row 단위 이동(dataDragDrop 동작 -> target1 행 감소, target2 행 증가).
    $c.gcm.createLabel('label="좌(target1)=소스(dataDragDrop=true 고정), 우(target2)=대상. con(dataDragDropCell)=[' + (vCell === '' ? '미설정' : vCell) + ']. [Target 재생성] 후 한 셀(또는 행)을 target1 에서 target2 로 Drag&Drop 하고 [양 그리드 데이터 출력] 으로 확인: Cell=true 면 행 수 불변+셀 1개만 이동(dataDragDrop 무시), Cell=false/미설정 면 target1 행 감소+target2 행 증가(Row 이동)."', '', 'label1');

    let strNameSpace = $c.gcm.getNameSpace();

    // === 소스 DataList(dlt_src) : Column 순서 [text, text, text, text], ID col1~col4 ===
    let strSrc = '';
    strSrc += '<w2:dataList ' + strNameSpace + ' id="dlt_src" baseNode="list" repeatNode="map">';
    strSrc += '<w2:columnInfo>';
    strSrc += '<w2:column id="col1" name="col1" dataType="text"></w2:column>';
    strSrc += '<w2:column id="col2" name="col2" dataType="text"></w2:column>';
    strSrc += '<w2:column id="col3" name="col3" dataType="text"></w2:column>';
    strSrc += '<w2:column id="col4" name="col4" dataType="text"></w2:column>';
    strSrc += '</w2:columnInfo>';
    strSrc += '<w2:data use="true"></w2:data>';
    strSrc += '</w2:dataList>';
    $p.data.create(strSrc);

    // === 대상 DataList(dlt_dst) : Column 순서 동일, ID 는 colA~colD (서로 다른 DataList) ===
    let strDst = '';
    strDst += '<w2:dataList ' + strNameSpace + ' id="dlt_dst" baseNode="list" repeatNode="map">';
    strDst += '<w2:columnInfo>';
    strDst += '<w2:column id="colA" name="colA" dataType="text"></w2:column>';
    strDst += '<w2:column id="colB" name="colB" dataType="text"></w2:column>';
    strDst += '<w2:column id="colC" name="colC" dataType="text"></w2:column>';
    strDst += '<w2:column id="colD" name="colD" dataType="text"></w2:column>';
    strDst += '</w2:columnInfo>';
    strDst += '<w2:data use="true"></w2:data>';
    strDst += '</w2:dataList>';
    $p.data.create(strDst);

    // 소스 데이터 4행 (전부 text 컬럼 : 숫자 셀 D&D 엔진버그 회피)
    let srcData = [
        { "col1": "행1", "col2": "백", "col3": "Aa", "col4": "가" },
        { "col1": "행2", "col2": "이백", "col3": "Bb", "col4": "나" },
        { "col1": "행3", "col2": "삼백", "col3": "Cc", "col4": "다" },
        { "col1": "행4", "col2": "사백", "col3": "Dd", "col4": "라" }
    ];
    dlt_src.setJSON(srcData, false);

    // 대상 데이터 2행 (이동 결과 행 수/셀값 변동 확인용)
    let dstData = [
        { "colA": "대상1", "colB": "십일", "colC": "Xx", "colD": "마" },
        { "colA": "대상2", "colB": "이이", "colC": "Yy", "colD": "바" }
    ];
    dlt_dst.setJSON(dstData, false);

    let grp_comp = $c.gcm.getTestGroup();

    // === 소스 그리드(target1) : dataDragDrop=true 고정 + dataDragDropCell 은 con 값 적용('' 이면 속성 미부여) ===
    let srcProps = { dataList: "data:dlt_src", dataDragDrop: true };
    if (vCell === 'true') { srcProps.dataDragDropCell = true; } else if (vCell === 'false') { srcProps.dataDragDropCell = false; }
    let srcCList = $c.gcm.createCList(srcProps);

    let strTarget1 = '';
    strTarget1 += '<w2:gridView ' + strNameSpace + ' ' + srcCList + ' id="" style="width:440px;height:300px;display:inline-block;vertical-align:top;">';
    strTarget1 += '<w2:caption style="" id="caption1" value="target1 (Drag 소스 / dlt_src / dataDragDrop=true)"></w2:caption>';
    strTarget1 += '<w2:header style="" id="header1">';
    strTarget1 += '<w2:row style="" id="hrow1">';
    strTarget1 += '<w2:column width="85" style="" inputType="text" id="hcol1" value="col1"></w2:column>';
    strTarget1 += '<w2:column width="85" style="" inputType="text" id="hcol2" value="col2"></w2:column>';
    strTarget1 += '<w2:column width="85" style="" inputType="text" id="hcol3" value="col3"></w2:column>';
    strTarget1 += '<w2:column width="85" style="" inputType="text" id="hcol4" value="col4"></w2:column>';
    strTarget1 += '</w2:row>';
    strTarget1 += '</w2:header>';
    strTarget1 += '<w2:gBody style="" id="gBody1">';
    strTarget1 += '<w2:row style="" id="brow1">';
    strTarget1 += '<w2:column width="85" style="" inputType="text" dataType="text" id="col1" dataList="col1"></w2:column>';
    strTarget1 += '<w2:column width="85" style="" inputType="text" dataType="text" id="col2" dataList="col2"></w2:column>';
    strTarget1 += '<w2:column width="85" style="" inputType="text" dataType="text" id="col3" dataList="col3"></w2:column>';
    strTarget1 += '<w2:column width="85" style="" inputType="text" dataType="text" id="col4" dataList="col4"></w2:column>';
    strTarget1 += '</w2:row>';
    strTarget1 += '</w2:gBody>';
    strTarget1 += '</w2:gridView>';

    scwin.target1 = await $p.dynamicCreate("target1", "gridView", strTarget1, grp_comp);

    // === 대상 그리드(target2) : Drop 대상. dataDragDrop=true + dataDragDropCell 은 con 동일 적용(Drop 수용 일치) ===
    let dstProps = { dataList: "data:dlt_dst", dataDragDrop: true };
    if (vCell === 'true') { dstProps.dataDragDropCell = true; } else if (vCell === 'false') { dstProps.dataDragDropCell = false; }
    let dstCList = $c.gcm.createCList(dstProps);

    let strTarget2 = '';
    strTarget2 += '<w2:gridView ' + strNameSpace + ' ' + dstCList + ' id="" style="width:440px;height:300px;display:inline-block;vertical-align:top;margin-left:12px;">';
    strTarget2 += '<w2:caption style="" id="caption2" value="target2 (Drop 대상 / dlt_dst / dataDragDrop=true)"></w2:caption>';
    strTarget2 += '<w2:header style="" id="header2">';
    strTarget2 += '<w2:row style="" id="hrow2">';
    strTarget2 += '<w2:column width="85" style="" inputType="text" id="hcolA" value="colA"></w2:column>';
    strTarget2 += '<w2:column width="85" style="" inputType="text" id="hcolB" value="colB"></w2:column>';
    strTarget2 += '<w2:column width="85" style="" inputType="text" id="hcolC" value="colC"></w2:column>';
    strTarget2 += '<w2:column width="85" style="" inputType="text" id="hcolD" value="colD"></w2:column>';
    strTarget2 += '</w2:row>';
    strTarget2 += '</w2:header>';
    strTarget2 += '<w2:gBody style="" id="gBody2">';
    strTarget2 += '<w2:row style="" id="brow2">';
    strTarget2 += '<w2:column width="85" style="" inputType="text" dataType="text" id="colA" dataList="colA"></w2:column>';
    strTarget2 += '<w2:column width="85" style="" inputType="text" dataType="text" id="colB" dataList="colB"></w2:column>';
    strTarget2 += '<w2:column width="85" style="" inputType="text" dataType="text" id="colC" dataList="colC"></w2:column>';
    strTarget2 += '<w2:column width="85" style="" inputType="text" dataType="text" id="colD" dataList="colD"></w2:column>';
    strTarget2 += '</w2:row>';
    strTarget2 += '</w2:gBody>';
    strTarget2 += '</w2:gridView>';

    scwin.target2 = await $p.dynamicCreate("target2", "gridView", strTarget2, grp_comp);
};



// 양 그리드 데이터 출력 : 적용 옵션(dataDragDrop=true / dataDragDropCell=con값) + 양 그리드 행 수 + 행별 셀값 출력
//  - Drag 전후 비교로 검증:
//    · Cell=true  -> 양 그리드 행 수 불변 + 특정 셀 1개만 변경(=dataDragDrop 무시, Cell 단위 동작)
//    · Cell=false/미설정 -> target1 행 감소 + target2 행 증가(=dataDragDrop Row 단위 이동 동작)
scwin.btn_dumpData_onclick = function () {
    let b = wf_body_bottom.getObj("scwin");

    // 소스(target1)에 적용된 옵션값
    let opt = target1.options;
    b.setReturnValue("적용 : dataDragDrop=" + opt.dataDragDrop + " / dataDragDropCell=" + opt.dataDragDropCell);

    // 소스 그리드(dlt_src) : 행 수 + 행별 전체 컬럼 출력
    let srcCnt = dlt_src.getRowCount();
    b.setReturnValue("[소스(target1)/dlt_src] " + srcCnt + "행");
    for (let i = 0; i < srcCnt; i++) {
        b.setReturnValue("  행" + i + " : col1=" + dlt_src.getCellData(i, "col1") + ", col2=" + dlt_src.getCellData(i, "col2") + ", col3=" + dlt_src.getCellData(i, "col3") + ", col4=" + dlt_src.getCellData(i, "col4"));
    }

    // 대상 그리드(dlt_dst) : 행 수 + 행별 전체 컬럼 출력
    let dstCnt = dlt_dst.getRowCount();
    b.setReturnValue("[대상(target2)/dlt_dst] " + dstCnt + "행");
    for (let j = 0; j < dstCnt; j++) {
        b.setReturnValue("  행" + j + " : colA=" + dlt_dst.getCellData(j, "colA") + ", colB=" + dlt_dst.getCellData(j, "colB") + ", colC=" + dlt_dst.getCellData(j, "colC") + ", colD=" + dlt_dst.getCellData(j, "colD"));
    }
};
